    n: 14, alerts: [['CRITICAL', 'wan1 loss 100%, both directions', 'aruba', `${b.code}-ec01 · wan1`, '100%'], ['INFO', 'Failover to wan2 in 4 s', 'aruba', `${b.code}-ec01`, '4 s'], ['CRITICAL', 'NTE line-side loss of signal', 'opsramp', `${b.code}-nte01`, 'LOS'], ['WARNING', '2 more circuits alarmed in the same central office', 'carrier', 'AT&T CO', '2']],
